"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[898],{7557:e=>{e.exports=JSON.parse('{"functions":[{"name":"get","desc":"Returns the current value without yielding.\\n\\nOn the client, errors if the value hasn\'t arrived yet. Call [Sencha.waitForReplicators] while loading, or use\\n[TemporaryGlobalReplicator:getAsync] or [TemporaryGlobalReplicator:observe] in code that may run earlier.\\n\\nOn the client, this includes pending predictions. [TemporaryGlobalReplicator:getConfirmed] returns the server\'s value\\nwithout them.","params":[],"returns":[{"desc":"","lua_type":"T"}],"function_type":"method","source":{"line":138,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}},{"name":"getAsync","desc":"Returns the current value, yielding until it\'s available. The server value always exists, so this only yields on the\\nclient.\\n\\nOn the client, this includes pending predictions. [TemporaryGlobalReplicator:getConfirmed] returns the server\'s value\\nwithout them.","params":[],"returns":[{"desc":"","lua_type":"T"}],"function_type":"method","yields":true,"source":{"line":159,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}},{"name":"set","desc":"Sets the value and sends it to every player. Errors if the value doesn\'t match the replicator\'s type. Setting a\\nprimitive to the value it already has does nothing; setting a table always counts as a change.","params":[{"name":"value","desc":"","lua_type":"T"}],"returns":[],"function_type":"method","realm":["Server"],"source":{"line":177,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}},{"name":"tryUpdate","desc":"Calls `callback` with the current value. If it returns `true` and a new value, the value is set as with\\n[TemporaryGlobalReplicator:set]; if it returns `false`, nothing changes. Returns what `callback` returned first.\\n\\n`callback` must not yield, so nothing else can change the value between reading and setting it.\\n\\n```lua\\nlocal didStart = EventsNetwork.meteorShowerReplicator:tryUpdate(function(isActive)\\n\\tif isActive then\\n\\t\\treturn false\\n\\tend\\n\\treturn true, true\\nend)\\n```","params":[{"name":"callback","desc":"","lua_type":"(value: T) -> (boolean, T?)"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"method","realm":["Server"],"source":{"line":204,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}},{"name":"applyIncrementalUpdate","desc":"Applies `patch` to the value with the incremental config\'s `apply`, then sends only the patch to every player.\\nErrors if the patch or the new value doesn\'t match its type, or if the replicator has no incremental config. An\\nempty table patch does nothing.","params":[{"name":"patch","desc":"","lua_type":"P"}],"returns":[],"function_type":"method","realm":["Server"],"source":{"line":229,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}},{"name":"onChanged","desc":"Calls `callback` when the value changes, not for the initial value.\\n\\nOn the server, the change is sent to clients before `callback` runs, so anything it changes in response reaches\\nclients after the change that caused it.\\n\\nOn the client, this also fires when a prediction is made, and again if it\'s rolled back. Use\\n[TemporaryGlobalReplicator:onConfirmedChanged] to only hear about the server\'s changes.","params":[{"name":"callback","desc":"","lua_type":"(newValue: T, oldValue: T) -> ()"}],"returns":[{"desc":"","lua_type":"Disconnect"}],"function_type":"method","source":{"line":274,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}},{"name":"observe","desc":"Calls `callback` with the current value right away if it has arrived (otherwise when it arrives), then on\\nevery change. `oldValue` is the value before the change, or `nil` for the first call.\\n\\n```lua\\nEventsNetwork.meteorShowerReplicator:observe(function(isActive, wasActive)\\n\\tif isActive and wasActive ~= true then\\n\\t\\tprint(\\"a meteor shower started\\")\\n\\tend\\nend)\\n```\\n\\nThis includes predictions: it fires when a prediction is made, and again if it\'s rolled back.","params":[{"name":"callback","desc":"","lua_type":"(newValue: T, oldValue: T?) -> ()"}],"returns":[{"desc":"","lua_type":"Disconnect"}],"function_type":"method","realm":["Client"],"source":{"line":310,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}},{"name":"onUpdateReceived","desc":"Calls `callback` for each patch received, after the value is updated. Only replicators with an incremental\\nconfig receive patches; calling this on one without errors.\\n\\nWhole values (the first value, or a `set`) don\'t fire this; use\\n[TemporaryGlobalReplicator:onChanged] to see every change.\\n\\nPatches always come from the server: predictions don\'t fire this, and `newValue` and `oldValue` are the\\nserver\'s values.","params":[{"name":"callback","desc":"","lua_type":"(newValue: T, oldValue: T, patch: P) -> ()"}],"returns":[{"desc":"","lua_type":"Disconnect"}],"function_type":"method","realm":["Client"],"source":{"line":335,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}},{"name":"getObservable","desc":"Returns an [ObservableValue](https://jdevon.github.io/observable-value/) that follows the replicated value,\\nfor code that works with ObservableValues, like the\\n[ReactObservableValue](https://github.com/JDevon/react-observable-value) hooks. Calling this again returns the same\\none. Setting it doesn\'t change the replicated value. Errors if the value hasn\'t arrived yet.\\n\\n```lua\\nlocal isMeteorShower = ReactObservableValue.useObservableValue(EventsNetwork.meteorShowerReplicator:getObservable())\\n```\\n\\nThe observable includes pending predictions, like [TemporaryGlobalReplicator:get].","params":[],"returns":[{"desc":"","lua_type":"ObservableValue<T>"}],"function_type":"method","realm":["Client"],"source":{"line":361,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}},{"name":"getConfirmed","desc":"Returns the value the server sent, without any pending predictions. [TemporaryGlobalReplicator:get] returns the\\npredicted value while a prediction is pending; use this when code must only act on what the server has confirmed.\\nErrors if the value hasn\'t arrived yet.","params":[],"returns":[{"desc":"","lua_type":"T"}],"function_type":"method","realm":["Client"],"source":{"line":379,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}},{"name":"onConfirmedChanged","desc":"Calls `callback` when the server\'s value changes, not for predictions or the initial value.\\n\\n[TemporaryGlobalReplicator:onChanged] also fires for predictions, and again if a wrong prediction is rolled back.\\nUse this instead for effects that should only change for confirmed values:\\n\\n```lua\\nEventsNetwork.meteorShowerReplicator:onConfirmedChanged(function(isActive, wasActive)\\n\\tif isActive and not wasActive then\\n\\t\\tannounceMeteorShower()\\n\\tend\\nend)\\n```","params":[{"name":"callback","desc":"","lua_type":"(newValue: T, oldValue: T) -> ()"}],"returns":[{"desc":"","lua_type":"Disconnect"}],"function_type":"method","realm":["Client"],"source":{"line":405,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}},{"name":"prediction","desc":"Builds a prediction for this replicator. The returned prediction can be used with a predicted remote call such as\\n`invokeServerPredicted` or `fireServerPredicted`. While the call is pending, [TemporaryGlobalReplicator:get],\\n[TemporaryGlobalReplicator:observe] and [TemporaryGlobalReplicator:onChanged] show the value with the prediction\\napplied; it\'s removed when the server confirms the call.\\n\\n`predict` is either a function that returns the predicted value, or a patch on a replicator with an incremental\\nconfig. A patch is applied with the config\'s `apply`, the same way the server\'s patches are.\\n\\n```lua\\nEventsNetwork.startMeteorShowerRemote:fireServerPredicted({\\n\\tEventsNetwork.meteorShowerReplicator:prediction(function()\\n\\t\\treturn true\\n\\tend),\\n})\\n```","params":[{"name":"predict","desc":"","lua_type":"((value: T) -> T) | P"}],"returns":[{"desc":"","lua_type":"Prediction"}],"function_type":"method","realm":["Client"],"source":{"line":439,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}},{"name":"isLoaded","desc":"Returns whether the value has arrived from the server.","params":[],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"method","realm":["Client"],"source":{"line":456,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}}],"properties":[],"types":[],"name":"TemporaryGlobalReplicator","desc":"One value the server keeps in memory and sends to every player, created with\\n`Sencha.temporaryReplicator.global`. Per-player data never goes through a global replicator unless you put it\\nthere, so the server always chooses what becomes public.","source":{"line":25,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}}')}}]);